 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background] * w for _ in range(h)]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            queue = deque([(r, c)])
            seen[r][c] = True
            component = []
            while queue:
                y, x = queue.popleft()
                component.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        queue.append((ny, nx))
            minr = min(y for y, x in component); maxr = max(y for y, x in component)
            minc = min(x for y, x in component); maxc = max(x for y, x in component)
            area = (maxr-minr+1) * (maxc-minc+1)
            if area >= 8 and len(component) / area >= 0.65:
                for y in range(minr, maxr+1):
                    for x in range(minc, maxc+1):
                        out[y][x] = color
    return out
